function compute(inputs){
  const f = inputs.f;
  const fs = inputs.fs;
  const Ts = 1/fs;
  const fN = 2*f;
  const k = Math.round(f/fs);
  const fa = Math.abs(f - k*fs);
  const aliased = fs < fN;
  const T = 1;
  const N = 200;
  const t = [];
  const orig = [];
  const recon = [];
  for(let i=0;i<N;i++){
    const ti = i*T/(N-1);
    t.push(ti);
    orig.push(Math.sin(2*Math.PI*f*ti));
    recon.push(Math.sin(2*Math.PI*fa*ti));
  }
  const sampleT = [];
  const sampleY = [];
  const nMax = Math.floor(T/Ts);
  for(let n=0;n<=nMax;n++){
    const tn = n*Ts;
    sampleT.push(tn);
    sampleY.push(Math.sin(2*Math.PI*f*tn));
  }
  const series = {
    x: t,
    lines: [
      {name: 'Original', y: orig},
      {name: 'Reconstructed', y: recon}
    ],
    marker: {x: sampleT, y: sampleY}
  };
  const table = {
    columns: ['Quantity', 'Value'],
    rows: [
      ['f (Hz)', f.toFixed(2)],
      ['f_s (Hz)', fs.toFixed(2)],
      ['Nyquist rate 2f (Hz)', fN.toFixed(2)],
      ['Aliased?', aliased ? 'Yes' : 'No'],
      ['k = round(f/f_s)', k],
      ['f_a = |f - k f_s| (Hz)', fa.toFixed(2)]
    ]
  };
  let insight = '';
  if(aliased){
    insight = 'Sampling rate ' + fs.toFixed(1) + ' Hz is below the Nyquist rate ' + fN.toFixed(1) + ' Hz. The signal aliases to ' + fa.toFixed(2) + ' Hz.';
  } else {
    insight = 'Sampling rate ' + fs.toFixed(1) + ' Hz is above the Nyquist rate ' + fN.toFixed(1) + ' Hz. The reconstructed frequency equals the true frequency ' + f.toFixed(2) + ' Hz.';
  }
  return {
    series: series,
    table: table,
    fa: fa,
    fN: fN,
    aliased: aliased,
    insight: insight
  };
}
